module adder_16bit (
    input wire [15:0] a,
    input wire [15:0] b,
    input wire Cin,
    output wire [15:0] y,
    output wire Co
);

    wire [15:0] carry;

    // First bit addition
    assign {carry[0], y[0]} = a[0] + b[0] + Cin;

    // Remaining bits addition
    genvar i;
    generate
        for (i = 1; i < 16; i = i + 1) begin
            assign {carry[i], y[i]} = a[i] + b[i] + carry[i-1];
        end
    endgenerate

    // Final carry-out
    assign Co = carry[15];

endmodule

