module adder_32bit(A, B, S, C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [32:0] carry;
     assign carry[0] = 0;

     genvar i;
     generate
         for (i = 1; i <= 32; i = i + 1) begin : full_adder
             assign {carry[i], S[i]} = A[i] + B[i] + carry[i-1];
         end
     endgenerate

     assign C32 = carry[32];
endmodule

