module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire [33:1] carry;
    assign carry[1] = 0;

    genvar i;
    generate
        for (i = 1; i <= 32; i = i + 1) begin : full_adder
            assign S[i] = A[i] ^ B[i] ^ carry[i];
            assign carry[i+1] = (A[i] & B[i]) | (carry[i] & (A[i] ^ B[i]));
        end
    endgenerate

    assign C32 = carry[33];
endmodule

