module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    reg [DATA_WIDTH-1:0] pipeline_adda [0:STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] pipeline_addb [0:STG_WIDTH-1];
    reg pipeline_en [0:STG_WIDTH-1];
    reg [DATA_WIDTH:0] intermediate_result [0:STG_WIDTH-1];
    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                pipeline_adda[i] <= 0;
                pipeline_addb[i] <= 0;
                pipeline_en[i] <= 0;
                intermediate_result[i] <= 0;
            end
            o_en <= 0;
        end else begin
            pipeline_adda[0] <= adda;
            pipeline_addb[0] <= addb;
            pipeline_en[0] <= i_en;
            intermediate_result[0] <= adda + addb;

            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                pipeline_adda[i] <= pipeline_adda[i-1];
                pipeline_addb[i] <= pipeline_addb[i-1];
                pipeline_en[i] <= pipeline_en[i-1];
                intermediate_result[i] <= intermediate_result[i-1];
            end

            o_en <= pipeline_en[STG_WIDTH-1];
        end
    end

    assign result = intermediate_result[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    reg [DATA_WIDTH:0] pipeline_regs [STG_WIDTH-1:0];
    reg pipeline_en [STG_WIDTH-1:0];
    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                pipeline_regs[i] <= {DATA_WIDTH+1{1'b0}};
                pipeline_en[i] <= 1'b0;
            end
            o_en <= 1'b0;
        end else begin
            if (i_en) begin
                pipeline_regs[0] <= adda + addb;
                pipeline_en[0] <= 1'b1;
            end else begin
                pipeline_en[0] <= 1'b0;
            end

            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                pipeline_regs[i] <= pipeline_regs[i-1];
                pipeline_en[i] <= pipeline_en[i-1];
            end

            o_en <= pipeline_en[STG_WIDTH-1];
        end
    end

    assign result = pipeline_regs[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    reg [DATA_WIDTH-1:0] adda_reg [0:STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] addb_reg [0:STG_WIDTH-1];
    reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH-1];
    reg enable_pipeline [0:STG_WIDTH-1];

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_en <= 1'b0;
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= {DATA_WIDTH{1'b0}};
                addb_reg[i] <= {DATA_WIDTH{1'b0}};
                sum_reg[i] <= {DATA_WIDTH+1{1'b0}};
                enable_pipeline[i] <= 1'b0;
            end
        end else begin
            if (i_en) begin
                adda_reg[0] <= adda;
                addb_reg[0] <= addb;
                sum_reg[0] <= adda + addb;
                enable_pipeline[0] <= 1'b1;
            end else begin
                enable_pipeline[0] <= 1'b0;
            end

            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                adda_reg[i] <= adda_reg[i-1];
                addb_reg[i] <= addb_reg[i-1];
                sum_reg[i] <= sum_reg[i-1];
                enable_pipeline[i] <= enable_pipeline[i-1];
            end

            o_en <= enable_pipeline[STG_WIDTH-1];
        end
    end

    assign result = sum_reg[STG_WIDTH-1];

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

    reg [DATA_WIDTH:0] pipe_reg [STG_WIDTH-1:0];
    reg [STG_WIDTH-1:0] en_pipe;
