	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Internal signals
reg [WIDTH-1:0] mem [DEPTH-1:0];
reg [ADDR_WIDTH:0] wptr, rptr;
reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;
reg [ADDR_WIDTH:0] wptr_gray_sync, rptr_gray_sync;

// Write pointer logic
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		wptr <= 0;
		wptr_gray <= 0;
	end else if (winc && !wfull) begin
		wptr <= wptr + 1;
		wptr_gray <= (wptr + 1) ^ ((wptr + 1) >> 1);
	end
end

// Read pointer logic
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		rptr <= 0;
		rptr_gray <= 0;
	end else if (rinc && !rempty) begin
		rptr <= rptr + 1;
		rptr_gray <= (rptr + 1) ^ ((rptr + 1) >> 1);
	end
end

// Synchronize write pointer to read clock domain
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		wptr_gray_sync <= 0;
	end else begin
		wptr_gray_sync <= wptr_gray;
	end
end

// Synchronize read pointer to write clock domain
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		rptr_gray_sync <= 0;
	end else begin
		rptr_gray_sync <= rptr_gray;
	end
end

// Memory write logic
always @(posedge wclk) begin
	if (winc && !wfull) begin
		mem[wptr[ADDR_WIDTH-1:0]] <= wdata;
	end
end

// Memory read logic
assign rdata = mem[rptr[ADDR_WIDTH-1:0]];

// Full flag logic
assign wfull = ((wptr_gray ^ (DEPTH >> 1)) == rptr_gray_sync);

// Empty flag logic
assign rempty = (wptr_gray_sync == rptr_gray);

endmodule

module asyn_fifo#(
