end

// Synchronization for write pointer into read clock domain
always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		wptr_gray_sync <= 0;
		wptr_bin_sync <= 0;
	end else begin
		wptr_gray_sync <= wptr_gray;
		wptr_bin_sync <= wptr_gray_sync ^ (wptr_gray_sync >> 1);
	end
end

// Synchronization for read pointer into write clock domain
always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		rptr_gray_sync <= 0;
		rptr_bin_sync <= 0;
	end else begin
		rptr_gray_sync <= rptr_gray;
		rptr_bin_sync <= rptr_gray_sync ^ (rptr_gray_sync >> 1);
	end
end

// Full and empty flags
assign wfull = (wptr[ADDR_WIDTH:0] == {~rptr_bin_sync[ADDR_WIDTH], rptr_bin_sync[ADDR_WIDTH-1:0]});
assign rempty = (rptr[ADDR_WIDTH:0] == wptr_bin_sync[ADDR_WIDTH:0]);

