		rq2_wptr <= {wptr[ADDR_WIDTH:0]};
		if (rinc && !rempty) begin
			rptr <= rptr + 1;
		end
	end
end

// Read data
assign rdata = mem[rptr[ADDR_WIDTH-1:0]];

