wire [ADDR_WIDTH:0] wptr_gray_next, rptr_gray_next;

// Write pointer binary to gray
assign wptr_gray_next = (wptr >> 1) ^ wptr;
assign wptr_gray = (wptr >> 1) ^ wptr;

// Read pointer binary to gray
assign rptr_gray_next = (rptr >> 1) ^ rptr;
assign rptr_gray = (rptr >> 1) ^ rptr;

