module asyn_fifo#(
    parameter    WIDTH = 8,
    parameter    DEPTH = 16
)(
    input                    wclk    , 
    input                    rclk    ,   
    input                    wrstn   ,
    input                    rrstn   ,
    input                    winc    ,
    input                    rinc    ,
    input        [WIDTH-1:0] wdata   ,

    output wire              wfull   ,
    output wire              rempty  ,
    output wire [WIDTH-1:0]  rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Internal signals
reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [ADDR_WIDTH-1:0] wptr, rptr;
reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;
reg [ADDR_WIDTH:0] wptr_gray_sync1, wptr_gray_sync2;
reg [ADDR_WIDTH:0] rptr_gray_sync1, rptr_gray_sync2;

// Write pointer logic
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
        wptr_gray <= 0;
    end else if (winc && !wfull) begin
        wptr <= wptr + 1;
        wptr_gray <= (wptr + 1) ^ ((wptr + 1) >> 1);
        mem[wptr] <= wdata;
    end
end

// Read pointer logic
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
        rptr_gray <= 0;
    end else if (rinc && !rempty) begin
        rptr <= rptr + 1;
        rptr_gray <= (rptr + 1) ^ ((rptr + 1) >> 1);
    end
end

// Synchronization of write pointer to read clock domain
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end

// Synchronization of read pointer to write clock domain
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end

// Empty and full detection
assign rempty = (rptr_gray_sync2 == rptr_gray);
assign wfull = ((wptr_gray_sync2 ^ (DEPTH >> 1)) == wptr_gray);

// Read data output
assign rdata = mem[rptr];

endmodule

