   output reg rdy;

   reg [15:0] multiplicand, product;
   reg [7:0] multiplier;
   reg [3:0] count;
   reg [2:0] booth_code;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'b0;
         rdy <= 1'b0;
         multiplicand <= {8'b0, a};
         multiplier <= b;
         product <= 16'b0;
         count <= 4'b0;
      end else begin
         if (count < 8) begin
            booth_code = {multiplier[1:0], 1'b0};
            case (booth_code)
               3'b001, 3'b010: product = product + multiplicand;
               3'b011: product = product + (multiplicand << 1);
               3'b100: product = product - (multiplicand << 1);
               3'b101, 3'b110: product = product - multiplicand;
               default: product = product;
            endcase
            multiplicand = multiplicand << 1;
            multiplier = multiplier >> 1;
            count = count + 1;
         end else begin
            p <= product;
            rdy <= 1'b1;
         end
      end
   end
