               3'b101, 3'b110: product <= product - {multiplicand, 8'b0};
               default: product <= product;
            endcase
            multiplicand <= multiplicand << 1;
            multiplier <= multiplier >> 1;
            booth <= {multiplier[0], booth[2:1]};
            count <= count - 1;

            if (count == 1) begin
               p <= product;
               rdy <= 1'b1;
            end
         end
      end
   end
endmodule

`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplicand, product;
   reg [7:0] multiplier;
