   reg active;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         p <= 16'b0;
         rdy <= 1'b0;
         multiplicand <= 16'b0;
         multiplier <= 8'b0;
         product <= 16'b0;
         count <= 4'b0;
         active <= 1'b0;
      end else begin
         if (!active) begin
            multiplicand <= {8'b0, a};
            multiplier <= b;
            product <= 16'b0;
            count <= 4'b0;
            active <= 1'b1;
            rdy <= 1'b0;
         end else if (count < 8) begin
            if (multiplier[0]) begin
               product <= product + multiplicand;
            end
            multiplicand <= multiplicand << 1;
            multiplier <= multiplier >> 1;
            count <= count + 1;
         end else begin
            p <= product;
            rdy <= 1'b1;
            active <= 1'b0;
