         p <= 16'b0;
      end else begin
         if (!active) begin
            multiplicand <= {{8{a[7]}}, a};
            multiplier <= {{8{b[7]}}, b};
            product <= 16'b0;
            count <= 4'b0;
            active <= 1'b1;
            rdy <= 1'b0;
         end else if (count < 8) begin
            if (multiplier[0] == 1'b1) begin
               product <= product + multiplicand;
            end
            multiplicand <= multiplicand << 1;
            multiplier <= multiplier >> 1;
            count <= count + 1;
         end else begin
            active <= 1'b0;
            p <= product;
            rdy <= 1'b1;
