`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [7:0] multiplier, multiplicand;
   reg [15:0] product;
   reg [3:0] count;
   reg [2:0] booth_state;

   always @(posedge clk or posedge reset) begin
      if (reset) begin
         multiplier <= 0;
         multiplicand <= 0;
         product <= 0;
         count <= 0;
         booth_state <= 0;
         rdy <= 0;
         p <= 0;
      end else begin
         case (booth_state)
            3'b000: begin
               multiplier <= b;
               multiplicand <= a;
               product <= 0;
               count <= 8;
               booth_state <= 3'b001;
               rdy <= 0;
            end

            3'b001: begin
               if (count > 0) begin
                  if (multiplier[0] == 1'b1) begin
                     product = product + (multiplicand << (8 - count));
                  end
                  multiplier = multiplier >> 1;
                  count = count - 1;
               end else begin
                  booth_state <= 3'b010;
               end
            end

            3'b010: begin
               p <= product;
               rdy <= 1;
               booth_state <= 3'b000;
            end
         endcase
      end
   end
endmodule

