      if (reset) begin
         p <= 16'b0;
         rdy <= 1'b0;
         product <= 16'b0;
         multiplicand <= 16'b0;
         multiplier <= 8'b0;
         count <= 5'b0;
         busy <= 1'b0;
      end else begin
         if (!busy) begin
            multiplicand <= {{8{a[7]}}, a}; // Sign extension
            multiplier <= b;
            product <= 16'b0;
            count <= 5'd8;
            busy <= 1'b1;
            rdy <= 1'b0;
         end else begin
            if (count > 0) begin
               if (multiplier[0] == 1'b1) begin
                  product <= product + multiplicand;
               end
               multiplicand <= multiplicand << 1;
               multiplier <= multiplier >> 1;
               count <= count - 1;
            end else begin
               p <= product;
               rdy <= 1'b1;
               busy <= 1'b0;
            end
         end
      end
   end
