         if (count == 4'b0) begin
            multiplicand <= {8'b0, a};
            multiplier <= b;
            product <= 16'b0;
            rdy <= 1'b0;
            count <= 4'b1000; // 8 iterations for 8-bit multiplier
         end else begin
            if (multiplier[0] == 1'b1) begin
               product <= product + multiplicand;
            end
            multiplicand <= multiplicand << 1;
            multiplier <= multiplier >> 1;
            count <= count - 1;
            if (count == 4'b0001) begin
