module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Internal pipeline registers
reg [size-1:0] mul_a_reg1, mul_b_reg1;
reg [size-1:0] mul_a_reg2, mul_b_reg2;
reg [N-1:0] partial_product1;
reg [N-1:0] final_product;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_a_reg1 <= {size{1'b0}};
		mul_b_reg1 <= {size{1'b0}};
		mul_a_reg2 <= {size{1'b0}};
		mul_b_reg2 <= {size{1'b0}};
		partial_product1 <= {N{1'b0}};
		final_product <= {N{1'b0}};
		mul_out <= {N{1'b0}};
	end else begin
		// Stage 1: Register inputs
		mul_a_reg1 <= mul_a;
		mul_b_reg1 <= mul_b;

		// Stage 2: Register intermediate values
		mul_a_reg2 <= mul_a_reg1;
		mul_b_reg2 <= mul_b_reg1;
		partial_product1 <= mul_a_reg1 * mul_b_reg1;

		// Stage 3: Final output
		final_product <= partial_product1;
		mul_out <= final_product;
	end
end

endmodule

