module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

// Pipeline registers
reg [size-1:0] mul_a_pipe [0:1];
reg [size-1:0] mul_b_pipe [0:1];
reg [N-1:0] mul_pipe [0:1];

// Stage 1: Capture inputs
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_a_pipe[0] <= 0;
		mul_b_pipe[0] <= 0;
	end else begin
		mul_a_pipe[0] <= mul_a;
		mul_b_pipe[0] <= mul_b;
	end
end

// Stage 2: Perform multiplication
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_pipe[0] <= 0;
