		mul_a_pipe[1] <= mul_a_pipe[0];
		mul_b_pipe[1] <= mul_b_pipe[0];
		mul_pipe[0] <= mul_a_pipe[0] * mul_b_pipe[0];
	end
end

// Stage 3: Output result
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_pipe[1] <= 0;
		mul_out <= 0;
	end else begin
		mul_pipe[1] <= mul_pipe[0];
		mul_out <= mul_pipe[0];
	end
end

endmodule

