        case (aluc)
            ADD: begin
                {carry_out, result} = a + b;
                overflow_out = (a[31] == b[31]) && (result[31] != a[31]);
            end
            ADDU: begin
                result = a + b;
            end
            SUB: begin
                {carry_out, result} = a - b;
                overflow_out = (a[31] != b[31]) && (result[31] != a[31]);
            end
            SUBU: begin
                result = a - b;
            end
            AND: result = a & b;
            OR: result = a | b;
            XOR: result = a ^ b;
            NOR: result = ~(a | b);
            SLT: result = (a < b) ? 32'b1 : 32'b0;
            SLTU: result = ($unsigned(a) < $unsigned(b)) ? 32'b1 : 32'b0;
            SLL: result = b << a[4:0];
            SRL: result = b >> a[4:0];
            SRA: result = $signed(b) >>> a[4:0];
            SLLV: result = b << a[4:0];
            SRLV: result = b >> a[4:0];
            SRAV: result = $signed(b) >>> a[4:0];
            LUI: result = {b[15:0], 16'b0};
            default: result = 32'b0;
        endcase
        negative_out = result[31];
    end

    assign r = result;
    assign zero = (result == 32'b0);
    assign carry = carry_out;
    assign negative = negative_out;
    assign overflow = overflow_out;
    assign flag = carry_out | overflow_out | negative_out | zero;

endmodule

module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [15:0] temp_A;
    reg [7:0] temp_B;

    integer i;

    always @(*) begin
        quotient = 16'b0;
        remainder = 16'b0;
        temp_A = A;
        temp_B = {8'b0, B};

        for (i = 15; i >= 0; i = i - 1) begin
