module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire[7:0]clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [1:0] state, next_state;
	reg [7:0] clock_counter;

	assign clock = clock_counter;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= idle;
			clock_counter <= 8'd0;
			red <= 1'b0;
			yellow <= 1'b0;
			green <= 1'b0;
		end else begin
			state <= next_state;
			clock_counter <= clock_counter + 1;
		end
	end

	always @(*) begin
		case (state)
			idle: begin
				red = 1'b0;
				yellow = 1'b0;
				green = 1'b0;
				if (pass_request)
					next_state = s1_red;
				else
					next_state = idle;
			end

			s1_red: begin
				red = 1'b1;
				yellow = 1'b0;
				green = 1'b0;
				if (clock_counter == 8'd10) // Change state after 10 clock cycles
					next_state = s2_yellow;
				else
					next_state = s1_red;
			end

			s2_yellow: begin
				red = 1'b0;
				yellow = 1'b1;
				green = 1'b0;
				if (clock_counter == 8'd20) // Change state after 10 more clock cycles
					next_state = s3_green;
				else
					next_state = s2_yellow;
			end

			s3_green: begin
				red = 1'b0;
				yellow = 1'b0;
				green = 1'b1;
				if (clock_counter == 8'd30) // Change state after 10 more clock cycles
					next_state = idle;
				else
					next_state = s3_green;
			end

			default: begin
				red = 1'b0;
				yellow = 1'b0;
				green = 1'b0;
				next_state = idle;
			end
		endcase
	end

endmodule

