        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [1:0] state, next_state;
	reg [7:0] count;

	assign clock = count;

	// State Transition Logic
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			state <= idle;
		else
			state <= next_state;
	end

	// State Next Logic and Counter Logic
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			count <= 8'd0;
			next_state <= idle;
		end 
		else begin
			case (state)
				idle: begin
					count <= 8'd0;
					if (pass_request)
						next_state <= s1_red;
					else
						next_state <= idle;
				end
				s1_red: begin
					if (count < 8'd50) begin
						count <= count + 1;
						next_state <= s1_red;
					end else begin
						count <= 8'd0;
						next_state <= s2_yellow;
					end
				end
				s2_yellow: begin
					if (count < 8'd20) begin
						count <= count + 1;
						next_state <= s2_yellow;
					end else begin
						count <= 8'd0;
						next_state <= s3_green;
					end
				end
				s3_green: begin
					if (count < 8'd30) begin
						count <= count + 1;
						next_state <= s3_green;
					end else begin
						count <= 8'd0;
						next_state <= idle;
					end
				end
				default: begin
					count <= 8'd0;
					next_state <= idle;
				end
			endcase
		end
	end

	// Output Logic
	always @(state) begin
		case (state)
			idle: begin
				red = 1'b0;
				yellow = 1'b0;
				green = 1'b0;
			end
			s1_red: begin
				red = 1'b1;
				yellow = 1'b0;
				green = 1'b0;
			end
			s2_yellow: begin
				red = 1'b0;
				yellow = 1'b1;
				green = 1'b0;
			end
			s3_green: begin
				red = 1'b0;
				yellow = 1'b0;
				green = 1'b1;
			end
			default: begin
				red = 1'b0;
				yellow = 1'b0;
				green = 1'b0;
			end
		endcase
	end

endmodule

