                    next_state = s3_green;
                else
                    next_state = s2_yellow;
            end

            s3_green: begin
                red = 0;
                yellow = 0;
                green = 1;
                if (counter == 8'd150)
                    next_state = idle;
                else
                    next_state = s3_green;
            end

            default: begin
                red = 0;
                yellow = 0;
                green = 0;
                next_state = idle;
            end
        endcase
    end
endmodule

module traffic_light
