			counter <= 8'd0;
		end else begin
			state <= next_state;
			counter <= counter + 8'd1;
		end
	end

	always @(*) begin
		case (state)
			idle: begin
				red = 0;
				yellow = 0;
				green = 0;
				if (pass_request)
					next_state = s1_red;
				else
					next_state = idle;
			end
			s1_red: begin
				red = 1;
				yellow = 0;
				green = 0;
				if (counter == 8'd100) 
					next_state = s2_yellow;
				else 
					next_state = s1_red;
			end
			s2_yellow: begin
				red = 0;
				yellow = 1;
				green = 0;
				if (counter == 8'd150) 
