module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire[7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] counter;

    assign clock = counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            counter <= 8'b0;
        end else begin
            state <= next_state;
            counter <= counter + 1;
        end
    end

    always @(*) begin
        // Default outputs
        red = 0;
        yellow = 0;
        green = 0;
        next_state = state;

        case (state)
            idle: begin
                if (pass_request) begin
                    next_state = s1_red;
                end
            end
            s1_red: begin
                red = 1;
                if (counter == 8'd10) begin
                    next_state = s2_yellow;
                    counter = 8'b0; // Reset counter for next state
                end
            end
            s2_yellow: begin
                yellow = 1;
                if (counter == 8'd5) begin
                    next_state = s3_green;
                    counter = 8'b0; // Reset counter for next state
                end
            end
            s3_green: begin
                green = 1;
                if (counter == 8'd15) begin
                    next_state = idle;
                    counter = 8'b0; // Reset counter for next state
                end
            end
        endcase
    end

endmodule

